'use strict';

var fmt = require('util').format;

/**
 * A test logger that captures console output.
 */

module.exports = function(logger) {
  var buffer = [];
  if (logger.__capture_monkeypatch) {
    return;
  }

  logger.writeln = capture.bind(logger, logger.writeln);
  logger.write = capture.bind(logger, logger.write);
  logger.error = capture.bind(logger, logger.error);
  logger.info = capture.bind(logger, logger.info);
  logger.warn = capture.bind(logger, logger.warn);
  logger.debug = function() {};

  function capture(passthruFn) {
    var msg = fmt.apply(null, Array.prototype.slice.call(arguments, 1));
    buffer.push(msg);
    passthruFn.call(logger, msg);
  }

  logger.values = function(clear) {
    var res = buffer;
    if (clear || typeof clear === 'undefined') {
      buffer = [];
    }
    return res;
  };

  logger.clear = function() {
    buffer = [];
  };

  return logger;
};
